BADGE='<svg class="badge" viewBox="0 0 120 120" aria-hidden="true"><defs><path id="bp{0}" d="M60 60m-44 0a44 44 0 1 1 88 0a44 44 0 1 1-88 0"/></defs><text><textPath href="#bp{0}">en circulation · en circulation · en circulation ·</textPath></text></svg>'
HERO=[
f'''<section class="h1g" data-v="1" aria-label="Présentation"><h1><span class="ln"><span>Votre marque,</span></span><span class="ln"><span>en circulation.</span></span></h1><div class="foot"><div><p>{TXT}</p>{BTN}</div></div><div class="art">{CAR}</div>{BADGE.format(1)}</section>''',
f'''<section class="h2c" data-v="2" aria-label="Présentation"><h1><span class="ln"><span>Votre marque,</span></span><span class="ln"><span>en circulation.</span></span></h1><div class="art">{CAR}</div><div class="foot"><p>{TXT}</p>{BTN}</div></section>''',
f'''<section class="h3d" data-v="3" aria-label="Présentation"><div class="side" aria-hidden="true"><span>roam</span></div><div class="dg"><img src="img/p_kia.webp" alt="SUV habillé en orange garé dans une rue résidentielle" width="2400" height="1344"></div><div class="tx"><h1><span class="ln"><span>Votre marque,</span></span><span class="ln"><span>en circulation.</span></span></h1><p>{TXT}</p>{BTN}</div></section>''',
f'''<section class="h4r" data-v="4" aria-label="Présentation"><svg class="route" viewBox="0 0 1440 800" preserveAspectRatio="none" aria-hidden="true"><path d="M-40 640C200 520 260 180 520 240s120 420 400 330 200-420 560-300"/></svg><h1><span class="ln"><span>Votre marque,</span></span><span class="ln"><span>en circulation.</span></span></h1><div class="art">{CAR}</div><div class="foot"><p>{TXT}</p>{BTN}</div></section>''']
C_T='Des voitures roulent déjà. Autant qu\'elles parlent de vous.'
C_P=[('Votre message','Nous imaginons une campagne pensée pour la route.','d_b1_0'),('Nos véhicules','Nous l\'installons sur des voitures de particuliers et de flottes d\'entreprise, sous contrat avec nous.','d_c1_1'),('Vos zones','Votre marque circule dans les villes que vous visez.','d_a1_0')]
words=' '.join(f'<span class="w">{w}</span>' for w in (C_T+' Nous créons votre campagne, nous l\'installons sur des voitures de particuliers et d\'entreprises, et votre marque circule là où vivent vos clients.').split())
OBJ=[('o_pin','Vous nous dites où.','Bruxelles, Gand, Liège : vous choisissez vos zones.'),('o_bub','Nous disons quoi.','Nous imaginons la campagne avec vous.'),('o_car','La route fait le reste.','Votre marque roule, tous les jours.')]
CONCEPT=[
f'''<section class="c1p" data-v="1" aria-labelledby="c1t"><p class="eye">Notre concept</p><h2 id="c1t" class="sr">{C_T}</h2><p class="st" aria-hidden="false">{words}</p><figure class="im"><img loading="lazy" src="img/p_vw.webp" alt="Voiture compacte habillée en bleu dans une rue en soirée" width="2400" height="1344"></figure></section>''',
'<section class="c2s" data-v="2" aria-label="Notre concept">'+f'<article class="pg p0"><p class="eye">Notre concept</p><h2 class="huge">{C_T}</h2></article>'+''.join(f'<article class="pg p{i+1}"><div><span class="n">{i+1}/3</span><h3 class="huge">{t}</h3><p>{d}</p></div><img loading="lazy" src="img/{m}.webp" alt="" width="640" height="460"></article>' for i,(t,d,m) in enumerate(C_P))+'</section>',
'<section class="c3o" data-v="3" aria-label="Notre concept">'+f'<header><p class="eye">Notre concept</p><h2 class="huge">{C_T}</h2></header>'+''.join(f'<div class="row r{i}"><img loading="lazy" src="img/{o}.webp" alt="" width="700" height="700"><div><h3 class="huge">{t}</h3><p>{d}</p></div></div>' for i,(o,t,d) in enumerate(OBJ))+'</section>']
Z=['Arrière','Rétroviseurs','Portes','Capot','Tout le véhicule']
S=[dict(n='Classique',p='La zone arrière et les rétroviseurs.',v='Berline',k=2,col='#101012',ct='#fff',f='a1',r='a2',d=['d_a2_0','d_a1_0','d_a2_1','d_a1_1','d_a2_2','d_a1_2','d_a1_3'],hf=[('Rétroviseurs',65,37,0)],hr=[('Rétroviseurs',18,40,0),('Zone arrière',81,52,1)]),
   dict(n='Medium',p='Les portes, l\'arrière, les rétroviseurs et le capot.',v='SUV compact',k=4,col='#F2600C',ct='#140A02',f='b1',r='b2',d=['d_b1_0','d_b2_0','d_b1_1','d_b2_1','d_b1_2','d_b2_2','d_b1_3'],hf=[('Capot',22,42,0),('Rétroviseurs',64,32,0),('Portes',74,52,0)],hr=[('Rétroviseurs',16,31,0),('Portes',31,50,0),('Zone arrière',80,46,1)]),
   dict(n='Complet',p='Toute la voiture, hors vitres.',v='Compacte',k=5,col='#1530C8',ct='#fff',f='c1',r='c2',d=['d_c1_0','d_c2_0','d_c1_1','d_c2_1','d_c1_2','d_c2_2','d_c1_3'],hf=[('Capot',25,52,0),('Toit',50,21,0),('Portes',68,52,0)],hr=[('Toit',45,20,0),('Portes',32,59,0),('Hayon',87,57,1)])]
zs=lambda s:'<ul class="zs">'+''.join(f'<li class="{"on" if i<s["k"] else ""}">{z}</li>' for i,z in enumerate(Z))+'</ul>'
car=lambda n,a:f'<img loading="lazy" src="img/s_{n}.webp" alt="{a}" width="2200" height="1238">'
hs=lambda p:''.join(f'<span class="hs{" l" if l else ""}" style="left:{x}%;top:{y}%"><i></i><b>{n}</b></span>' for n,x,y,l in p)
POS=[(4,8),(80,14),(18,46),(70,50),(2,70),(84,74),(44,82)]
F1='<section class="f1" data-v="1">'+''.join(f'''<article class="fw" style="--c:{s["col"]}"><div class="ct"><small>Style {i+1} sur 3 · {s["v"]}</small><h3 class="huge">{s["n"]}</h3><p>{s["p"]}</p>{zs(s)}</div><div class="ims">{"".join(f'<img loading="lazy" src="img/{d}.webp" alt="" width="640" height="460" style="left:{POS[j][0]}%;top:{POS[j][1]}%">' for j,d in enumerate(s["d"]))}</div><div class="whole">{car(s["f"],s["n"]+" : "+s["p"])}</div></article>''' for i,s in enumerate(S))+'</section>'
F2='<section class="f2" data-v="2">'+''.join(f'''<article class="fy" style="--c:{s["col"]};--ct:{s["ct"]}"><div class="pg"><h3 class="mega">{s["n"]}</h3>{car(s["f"],s["n"]+" : "+s["p"])}<p class="sub">Style {i+1} sur 3 · {s["v"]}</p></div><div class="sheetp"><p class="say">{"".join(f'<span class="w">{w} </span>' for w in s["p"].split())}</p>{zs(s)}<div class="fan">{"".join(f'<img loading="lazy" src="img/{d}.webp" alt="" width="640" height="460">' for d in s["d"][:4])}</div></div></article>''' for i,s in enumerate(S))+'</section>'
F3='<section class="f3" data-v="3"><div class="st3"><div class="cars">'+''.join(f'<div class="vw" data-s="{i}">{car(c,s["n"])}{hs(h)}</div>' for i,s in enumerate(S) for c,h in ((s["f"],s["hf"]),(s["r"],s["hr"])))+'</div><div class="lamp" aria-hidden="true"></div><div class="tt">'+''.join(f'<div class="t"><small>Style {i+1} sur 3 · {s["v"]}</small><h3 class="huge">{s["n"]}</h3><p>{s["p"]}</p></div>' for i,s in enumerate(S))+'</div><div class="line">'+''.join(f'<figure>{car(s["f"],s["n"])}<figcaption>{s["n"]}</figcaption></figure>' for s in S)+'</div></div></section>'
F4='<section class="f4" data-v="4"><div class="names" role="tablist" aria-label="Styles de campagne">'+''.join(f'<button role="tab" id="f4t{i}" aria-selected="{"true" if i==0 else "false"}" aria-controls="f4p" data-i="{i}"><i>{i+1}</i><span>{s["n"]}</span></button>' for i,s in enumerate(S))+'</div><div class="pane" id="f4p" role="tabpanel" aria-labelledby="f4t0" tabindex="0"><div class="pics">'+''.join(f'<div class="pic" data-s="{i}" data-w="{w}">{car(c,s["n"])}{hs(h)}</div>' for i,s in enumerate(S) for w,(c,h) in enumerate(((s["f"],s["hf"]),(s["r"],s["hr"]))))+'</div><div class="meta"><div class="sw" role="group" aria-label="Vue"><button data-w="0" aria-pressed="true">Avant</button><button data-w="1" aria-pressed="false">Arrière</button></div>'+''.join(f'<div class="inf" data-s="{i}"><p>{s["p"]}</p>{zs(s)}</div>' for i,s in enumerate(S))+'</div></div></section>'
E=[('Conception graphique','Nous créons vos visuels ou adaptons les vôtres aux surfaces du véhicule.','d_b1_0','Concevoir','<path d="M4 20l4-1L19 8l-3-3L5 16z"/>'),('Covering et pose','Nous préparons, imprimons et posons le film. Les vitres restent libres.','d_c1_1','Poser','<path d="M4 8h16v9H4zM4 12h16"/>'),('Diffusion sur véhicules','Votre campagne circule au quotidien dans les zones définies avec vous.','d_a2_2','Diffuser','<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="2.5"/>'),('Suivi des campagnes','Vous recevez des rapports sur les données réellement disponibles.','d_b2_1','Suivre','<path d="M4 18l6-6 4 4 6-8"/>')]
E1='<section class="e1" data-v="1"><div class="deck">'+''.join(f'<article class="tk"><header><span>N° {i+1:02d}</span><span>roam</span></header><h3>{t}</h3><p>{d}</p><div class="cut"></div><div class="bars" aria-hidden="true"></div></article>' for i,(t,d,*_) in enumerate(E))+'</div></section>'
E2='<section class="e2" data-v="2"><ul>'+''.join(f'<li><h3 class="giant"><span>{w}</span><svg viewBox="0 0 24 24" aria-hidden="true">{ic}</svg></h3><div class="d"><b>{t}</b><p>{d}</p></div></li>' for t,d,m,w,ic in E)+'</ul></section>'
E3='<section class="e3" data-v="3"><ol>'+''.join(f'<li tabindex="0"><span class="n">({i+1})</span><h3><span class="rl" data-t="{t}">{t}</span></h3><p>{d}</p></li>' for i,(t,d,*_) in enumerate(E))+'</ol><div class="pv" aria-hidden="true">'+''.join(f'<img loading="lazy" src="img/{m}.webp" alt="" width="640" height="460">' for _,_,m,*_ in E)+'</div></section>'
MAP=(ROOT/'src/be_path.txt').read_text().strip()
TOP=lambda a,b:f'<div class="top"><span>{a}</span><span class="tg">{b}</span></div>'
SC=[('zones','Vos zones',f'<div class="pscr">{TOP("Ma campagne","Active")}<div class="mapui"><svg viewBox="0 0 256 210"><path d="{MAP}"/><circle cx="121.8" cy="70" r="24"/><circle cx="81.8" cy="50" r="19"/><circle cx="125" cy="33" r="15"/><circle class="d" cx="121.8" cy="70" r="3"/><circle class="d" cx="81.8" cy="50" r="3"/><circle class="d" cx="125" cy="33" r="3"/></svg></div><div class="tags"><b>Bruxelles</b><b>Gand</b><b>Anvers</b></div></div>','Vos zones sur la carte, dès que la campagne démarre.'),
    ('km','Vos kilomètres',f'<div class="pscr">{TOP("Kilomètres","Ce mois")}<div class="bigm"><u style="--w:34%"></u><u style="--w:52%"></u><u style="--w:46%"></u><u style="--w:70%"></u><u style="--w:62%"></u><u style="--w:84%"></u><u style="--w:76%"></u></div><div class="card"><span>Bruxelles</span><i class="meter"><u style="width:70%"></u></i></div><div class="card"><span>Gand</span><i class="meter"><u style="width:48%"></u></i></div><div class="card"><span>Anvers</span><i class="meter"><u style="width:36%"></u></i></div></div>','Le chemin parcouru par votre campagne, zone par zone.'),
    ('public','Votre public',f'<div class="pscr">{TOP("Public touché","Estimation")}<div class="ring"><i></i></div><div class="card"><span>Par zone</span><i class="meter"><u style="width:54%"></u></i></div><div class="pbtn">Voir le rapport</div></div>','Une estimation du public touché, avec un rapport à télécharger.'),
    ('mois','Mon mois',f'<div class="pscr">{TOP("Mon mois","Conducteur")}<div class="card tall"><span>Objectif du mois</span><i class="meter"><u style="width:78%"></u></i><span>Kilomètres à valider</span></div><div class="card"><span>Mes grandes zones</span><div class="tags"><b>Bruxelles</b><b>Gand</b></div></div><div class="pbtn">Valider mon mois</div></div>','Pour les conducteurs : valider ses kilomètres et ses grandes zones.')]
PH=lambda inner:f'<div class="ph" aria-hidden="true"><div class="sc">{inner}</div></div>'
screens=''.join(f'<div class="ps">{h}</div>' for _,_,h,_ in SC)
A1='<section class="a1" data-v="1"><div class="st4"><div class="tt">'+''.join(f'<div class="t"><h3 class="huge">{t}</h3><p>{d}</p></div>' for _,t,_,d in SC)+f'</div>{PH(screens)}<div class="dots" aria-hidden="true">{"<i></i>"*4}</div></div></section>'
sp=lambda t:t.split(' ',1)
A2='<section class="a2" data-v="2"><div class="st5"><div class="flash"></div><div class="wl">'+''.join(f'<div class="wd"><span>{sp(t)[0]}</span><span>{sp(t)[1]}</span></div>' for _,t,_,_ in SC)+f'</div>{PH(screens+chr(60)+"nav class=tabs>"+"".join(f"<b>{t.split()[-1]}</b>" for _,t,_,_ in SC)+"<i></i></nav>")}<nav class="pill" aria-label="Étapes de l\'application">'+''.join(f'<button data-i="{i}">{t}</button>' for i,(_,t,_,_) in enumerate(SC))+'</nav></div></section>'
A3='<section class="a3" data-v="3"><div class="st6"><div class="bw">'+''.join(f'<h3 class="mega">{t}</h3>' for _,t,_,_ in SC)+f'</div>{PH(screens)}<div class="cap">'+''.join(f'<p>{d}</p>' for _,_,_,d in SC)+'</div></div></section>'
A4=f'<section class="a4" data-v="4"><div class="duo"><div class="one">{PH(SC[0][2])}<h3>Pour les annonceurs</h3><p>Vos zones, vos kilomètres et votre public estimé, au même endroit.</p></div><div class="one">{PH(SC[3][2])}<h3>Pour les conducteurs</h3><p>Vos kilomètres à valider et vos grandes zones, sans trajet détaillé.</p></div></div></section>'
t=(ROOT/'src/site_index.html').read_text()
for k,v in (('HERO',HERO),('CONCEPT',CONCEPT),('FORMATS',[F1,F2,F3,F4]),('EXPERTISE',[E1,E2,E3]),('APP',[A1,A2,A3,A4])):
    t=t.replace('{{'+k+'}}','\n'.join(v))
(ROOT/'site/index.html').write_text(t)
